#include <iostream>
#include <vector>

using namespace std;

int main()
{
    int n;
    cin >> n;

    vector<int> arr(n);

    int sum = 0;
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
        sum += arr[i];
    }

    if (sum == 0) {
        cout << n;
        return 0;
    }

    bool allow = (arr[0] == 0);

    vector<int> brr;
    for (int i = 0; i < n; ++i) {
        int cand = arr[i];
        if (cand == 1 || allow) {
            allow = false;
            brr.push_back(cand);
        } else {
            allow = true;
        }
    }

    cout << brr.size() << endl;
    return 0;
}

